# פרק 4 (שלד אוטומטי מהתוכן הקיים; להעמקה)
N=4
TITLE='פרשנות חוקים ותכלית החקיקה'
SUM=[' <p>חוק כתוב טעון <strong>פרשנות</strong>; עיקרון-העל בישראל הוא <strong>הפרשנות התכליתית</strong>.</p> <h3>4.1 הפרשנות התכליתית</h3> <p>מטרת הפרשנות היא לאתר את <strong>תכלית החקיקה</strong>. השלבים: מתחילים מ<strong>לשון החוק</strong> (הפרשנות חייבת לעגן בלשון), ומבין מגוון המשמעויות הלשוניות האפשריות בוחרים את זו ה<strong>מגשימה את התכלית</strong>.</p> <h3>4.2 תכלית סובייקטיבית ואובייקטיבית</h3> <p><strong>סובייקטיבית</strong> — כוונת המחוקק ההיסטורי (דברי הסבר, היסטוריה חקיקתית); <strong>אובייקטיבית</strong> — התכלית שחוק במדינה דמוקרטית נועד להגשים (ערכי היסוד של השיטה). בהתנגשות — נדרש איזון.</p> <h3>4.3 כללי עזר</h3> <p>חזקות פרשניות (כגון חזקת ההתאמה לחוקי היסוד), ופרשנות המקיימת את החוק ולא מבטלת אותו.</p> <h3>4.4 נקודות מפתח למבחן</h3> <ul><li>פרשנות תכליתית — מלשון החוק אל התכלית.</li><li>תכלית סובייקטיבית (כוונת המחוקק) מול אובייקטיבית (ערכי השיטה).</li><li>עיגון בלשון + חזקות פרשניות.</li></ul> <p style="margin-top:18px;padding-top:9px;border-top:1px solid var(--line,#3a342a);font-size:11px;color:var(--muted,#8a8475)">© כל הזכויות שמורות ל<b>אילן פרץ</b> · אין להעתיק, לשכפל או להפיץ ללא רשות בכתב.</p>']
CASES=[('ע״פ 267/54 היועץ המשפטי לממשלת ישראל נ׳ פסח שלפוברסקי ושות׳ בע״מ', 'נשאלה השאלה אם מפעל לטרקטורים חייב ברישיון לפי תוספת לפקודה מנדטורית שהזכירה "מכונית". המחוזי פסק לפי לשון בני אדם שטרקטור אינו מכונית.', 'העליון הפך את ההחלטה וקבע שטרקטור נכלל, אבל עשה זאת בניתוח לשוני: פנה לנוסח האנגלי המקורי (motor vehicles), למילונים ולחיקוקים דומים. הפרשה מייצגת את התקופה שבה מושא הפרשנות היה הלשון ולא התכלית, ומדגימה את חשיבות הנוסח המחייב (היום ס׳ 24 לחוק הפרשנות).'), ('ע״פ 787/79 מזרחי נ׳ מדינת ישראל', 'אסיר שיצא לחופשה ולא שב לכלא טען שלא ברח מ"משמורת חוקית", כי בזמן החופשה לא היה במשמורת פיזית.', 'השופט ברק קבע שיש לפרש את העבירה לפי תכליתה ולא לפי לשונה היבשה, ולכן גם מי שנמצא ב"משמורת רעיונית" — מחוץ לכלא אך נתון למרות השלטונות — עובר את העבירה. מכאן המשפט המפורסם שמילות החוק אינן "מבצרים שיש לכבשם בעזרת מילונים". הפרשה היא נקודת המפנה של הפרשנות התכליתית במשפט הפלילי, ובעקבותיה נקבע ב־1994 ס׳ 34כא.'), ('ע״א 165/82 קיבוץ חצור נ׳ פקיד שומה רחובות', 'קיבוץ שבבעלותו מפעל מאושר חויב במלווה ביטחון על הכנסתו לשנת 1975, והשאלה הייתה איזו הוראה בחוק לעידוד השקעות הון חלה עליו.', 'השופט ברק קבע שחוק מס מתפרש כמו כל חוק — לפי תכליתו; אין לפרשו לטובת הנישום ואין לפרשו לרעתו. הלשון היא נקודת המוצא ("לעולם יש לפתוח בלשון החוק, אך לעולם אין לסיים בה"). רק אם נותר ספק שלא ניתן להסירו — נוטים להגנה על חירות הפרט וקניינו. לגופו של עניין נקבע, על סמך דברי ההסבר, שהמטרה הייתה להטיל מלווה גם על קיבוץ, והערעור נדחה.'), ('ע״פ 2831/95 אלבה נ׳ מדינת ישראל', 'הרב עידוא אלבה פרסם מאמר על "הלכות הריגת גוי" והועמד לדין, לראשונה בישראל, בעבירת פרסום הסתה לגזענות.', 'ההרכב המורחב (שבעה שופטים) דחה ברוב דעות את הערעור על ההרשעה, אבל השופטים נחלקו בפרשנות יסודות העבירה: האם די במטרה להסית לגזענות (השופט מצא), או שנדרש גם שתוכן הפרסום יהיה גזעני (הנשיא ברק), והאם חל מבחן הסתברות. הפרשה ממחישה איך הכרעה פרשנית קובעת את גבולות האיסור הפלילי.'), ('בג״ץ 5555/18 חסון נ׳ הכנסת', 'עתירות לביטול חוק־יסוד: ישראל – מדינת הלאום של העם היהודי נדונו בהרכב של 11 שופטים.', 'העתירות נדחו ברוב של 10 שופטים. הנשיאה חיות קבעה שיש להעדיף פרשנות מקיימת, ככל שהיא אפשרית וסבירה, שלפיה החוק אינו פוגע בזכויות חוקתיות, על פני פרשנות שתוביל לביטולו. השופט קרא, בדעת מיעוט, סבר שאי אפשר לבסס פרשנות מקיימת על הנחות שאינן כתובות בחוק. בפסק הדין נקבע גם שהכנסת כרשות מכוננת אינה "כל יכולה".'), ('עע״מ 2484/23 קלמנט נ׳ משרד הפנים', 'דיון בערעור מינהלי בשאלה פרשנית בעניין החלטה של משרד הפנים (2024).', 'השופט שטיין מתח ביקורת על השימוש ב"תכלית האובייקטיבית" ככלי רב־עוצמה, וקבע שגם אם נפלה שגגה אצל המחוקק — אין זה תפקיד בית המשפט לתקנה בדרך של חקיקה שיפוטית בניגוד למשמעות הברורה של החוק. העמדה משקפת מגמה עכשווית בעליון לתת משקל רב יותר ללשון.')]
QS=[{'q': 'מהו "מתחם האפשרויות הלשוני" בפרשנות התכליתית?', 'o': ['המשמעות המילונית הראשונה של כל מילה בחוק', 'רשימת המונחים המוגדרים בסעיף 3 לחוק הפרשנות', 'המשמעות שהמחוקק התכוון אליה לפי דברי ההסבר', 'כל המשמעויות שהמילים מסוגלות לשאת בהקשרן, שמתוכן נבחרת המשמעות המגשימה את התכלית'], 'c': 3, 'e': 'נכון. בשלב הראשון מסמנים את כל המשמעויות שהלשון יכולה לשאת, ולמשמעות שנבחרת חייב להיות עיגון ולו מינימלי בלשון.'}, {'q': 'מה ההבדל המרכזי בין תכלית סובייקטיבית לתכלית אובייקטיבית?', 'o': ['סובייקטיבית חלה רק בחוקים פליליים, ואובייקטיבית רק בחוקי יסוד', 'סובייקטיבית נקבעת לפי דעת השופט, ואובייקטיבית לפי המילון', 'סובייקטיבית היא מה שהמחוקק בפועל ביקש להשיג; אובייקטיבית היא מה שמחוקק סביר בחברה דמוקרטית היה מבקש, לאור ערכי השיטה', 'אין הבדל — אלה שני שמות לאותו מושג'], 'c': 2, 'e': 'נכון. הסובייקטיבית היא כוונת המחוקק ההיסטורית; האובייקטיבית נגזרת מערכי היסוד ומחזקות התכלית, והיא דינמית.'}, {'q': 'מה קבע בית המשפט בפרשת קיבוץ חצור לגבי פרשנות חוקי מס?', 'o': ['חוק מס מתפרש לפי תכליתו כמו כל חוק, ורק ספק שלא ניתן להסירו מוכרע לאור ההגנה על חירות וקניין', 'חוק מס מתפרש לפי לשונו בלבד, בלי היסטוריה חקיקתית', 'חוק מס מתפרש תמיד לטובת הנישום', 'חוק מס מתפרש תמיד לטובת המדינה, כדי להגן על הקופה הציבורית'], 'c': 0, 'e': 'נכון. הכלל הוא פרשנות תכליתית; הדווקנות לטובת הנישום נשארה רק כמוצא אחרון כשהתכלית אינה מתבררת.'}, {'q': 'לפי הגישה הרווחת בפסיקה, מתי חל ס׳ 34כא לחוק העונשין?', 'o': ['רק בעבירות מסוג חטא', 'רק כשהחוק הפלילי נחקק לפני 1994', 'כשאחרי פרשנות תכליתית מלאה עדיין נותרו כמה פירושים סבירים', 'בכל פעם שהנאשם מציע פירוש לשוני אפשרי כלשהו שמקל איתו'], 'c': 2, 'e': 'נכון. המילים "לפי תכליתו" מחייבות קודם פרשנות תכליתית, וס׳ 34כא הוא כלל הכרעה אחרון לספק שנותר.'}, {'q': 'מה קבע ס׳ 34כא לחוק העונשין, בלשונו?', 'o': ['כל ספק בפרשנות חוק פלילי יוכרע לטובת הנאשם, בלי קשר לתכלית', 'חוק פלילי יתפרש לפי לשונו הפשוטה בלבד', 'בית המשפט רשאי לפרש חוק פלילי בהרחבה כאשר הדבר נדרש לשמירה על שלום הציבור', 'ניתן דין לפירושים סבירים אחדים לפי תכליתו — יוכרע העניין לפי הפירוש המקל ביותר עם מי שאמור לשאת באחריות פלילית לפי אותו דין'], 'c': 3, 'e': 'נכון. זה נוסח הסעיף: "ניתן דין לפירושים סבירים אחדים לפי תכליתו, יוכרע הענין לפי הפירוש המקל ביותר...".'}, {'q': 'אסיר יצא לחופשה מאושרת ולא חזר. בהגנתו טען שבזמן החופשה לא היה "במשמורת", ולכן לא ברח ממשמורת חוקית. לפי ההלכה, מה הדין?', 'o': ['הוא יזוכה, כי בשעת החופשה לא הייתה עליו שמירה פיזית', 'הוא יזוכה מכוח ס׳ 34כא, כי יש פירוש לשוני שמקל איתו', 'הוא עובר את העבירה, כי לפי תכליתה היא חלה גם על "משמורת רעיונית" של מי שנתון למרות השלטונות', 'הוא עובר עבירה רק אם לפני כן ניסה לברוח מהכלא עצמו'], 'c': 2, 'e': 'נכון. זו הלכת מזרחי: העבירה מתפרשת לפי תכליתה, וחלה גם על מי שנמצא מחוץ לכלא אך עדיין במשמורת "רעיונית".'}, {'q': 'חוק מס חדש ניתן לשני פירושים לשוניים. דברי ההסבר והמבנה מלמדים בבירור שהמחוקק התכוון לפירוש שמטיל מס. הנישום טוען שבחוק מס תמיד מפרשים לטובתו. מה הדין?', 'o': ['בית המשפט יבחר בפירוש שמגשים את התכלית — הטלת המס', 'בית המשפט יפנה לחוק יסודות המשפט, כי יש לקונה', 'בית המשפט חייב לבחור בפירוש שמכניס יותר כסף לקופה', 'הנישום צודק — זה כלל יסוד בדיני מסים'], 'c': 0, 'e': 'נכון. לפי חצור מפרשים לפי התכלית; כשהיא מתבררת, אין מקום לפירוש המקל עם הנישום.'}, {'q': 'תקנה קובעת: "לא יחזיק אדם בגן הציבורי כלב, חתול או בעל חיים אחר בלי רצועה". אדם הוליך תרנגול בלי רצועה וטען שהתקנה חלה רק על חיות מחמד דומות לכלב וחתול. מה מלמד ס׳ 7 לחוק הפרשנות?', 'o': ['יש לפנות למשפט העברי כדי לפרש את המילה "אחר"', 'הטענה נכונה — "אחר" מוגבל תמיד לפריטים דומים לרשימה', 'התקנה בטלה בשל עמימות', '"אחר" בא להבדיל מהמפורט ולא להקיש לו, ולכן ככלל חל על כל בעל חיים, אלא אם ההקשר מלמד אחרת'], 'c': 3, 'e': 'נכון. לפי ס׳ 7 המילים "או... אחר" באות להבדיל מן המפורט ולא להקיש לו, אלא אם נכתב "דומה" או "כיוצא בזה" — ובכפוף להקשר (ס׳ 1).'}, {'q': 'פקודה מנדטורית שנחקקה באנגלית ולא קיבלה נוסח חדש מתורגמת בספר החוקים בצורה שמשמיטה מילה. איזה נוסח מחייב?', 'o': ['אף נוסח אינו מחייב, ובית המשפט יכריע לפי התכלית בלבד', 'הנוסח האנגלי, כי זו השפה שבה ניתן הדין ולא נקבע לו נוסח חדש', 'הנוסח העברי, כי זו שפת המדינה', 'הנוסח שמקל יותר עם האזרח'], 'c': 1, 'e': 'נכון. לפי ס׳ 24 לחוק הפרשנות הנוסח המחייב הוא בשפה שבה ניתן הדין; רק נוסח חדש שנקבע לפי ס׳ 16 לפקודת סדרי השלטון והמשפט גובר.'}, {'q': 'בעתירה נגד חוק נטען שאחד מפירושיו פוגע בזכות חוקתית. לחוק יש גם פירוש סביר אחר שאינו פוגע. מה הכלל?', 'o': ['בית המשפט יעדיף את הפירוש שמקיים את החוק ואינו פוגע בזכויות, ככל שהוא אפשרי וסביר', 'בית המשפט יחזיר את החוק לכנסת לפרשנות מחייבת', 'בית המשפט יבחר בפירוש הסובייקטיבי בלבד', 'בית המשפט חייב לבטל את החוק בכל מקרה שיש לו פירוש פוגעני'], 'c': 0, 'e': 'נכון. זו פרשנות מקיימת, כפי שהודגשה בבג״ץ חוק הלאום: מעדיפים פירוש שאינו פוגע בזכויות, אם הוא אפשרי וסביר.'}, {'q': 'חוק שנחקק לפני שנה מתפרש. התכלית הסובייקטיבית (כוונת המחוקק) מעוגנת בלשון ומוכחת היטב, אבל מתנגשת עם תכלית אובייקטיבית כללית. לפי גישת ברק לגבי משקל התכליות, לאן נוטה הכף?', 'o': ['מכריעים לפי ס׳ 34כא', 'אין לתכלית הסובייקטיבית משקל לאחר שהחוק נחקק', 'התכלית הסובייקטיבית מקבלת משקל רב יותר בחוק חדש וספציפי', 'תמיד לתכלית האובייקטיבית, בכל סוגי החוקים'], 'c': 2, 'e': 'נכון. בחוק חדש וספציפי כוונת המחוקק ברורה ורלוונטית, ולכן מקבלת משקל רב יותר; בחוק ישן או בחוקה גדל משקל התכלית האובייקטיבית.'}, {'q': 'שופט רוצה לקבוע שחוק חל על מקרה, אף שאין לכך שום עיגון במילות החוק, משום שלדעתו זו התכלית הראויה. מה הבעיה לפי תורת הפרשנות התכליתית?', 'o': ['הבעיה היא רק אם מדובר בחוק פלילי', 'אין בעיה — התכלית גוברת תמיד על הלשון', 'הבעיה היא שהשופט לא בדק את דברי ההסבר', 'תכלית שאין לה עיגון מינימלי בלשון אינה יכולה להיות מוגשמת בדרך של פרשנות'], 'c': 3, 'e': 'נכון. בלי עיגון ולו מינימלי בלשון אין זו פרשנות אלא השלמת חסר או שינוי החוק.'}, {'q': 'נאשם הורשע לפי פרשנות מסוימת של עבירה. בדיון נוסף בעניין אחר אימץ העליון פרשנות מצמצמת לאותה עבירה. מה מלמדת פרשת ג׳בארין על השלכות מצב כזה?', 'o': ['שינוי פרשני כזה עשוי להוביל לבקשות של נאשמים שהורשעו לפי הפירוש הקודם', 'שינוי הפרשנות מחייב את הכנסת לתקן את החוק תוך 30 יום', 'השינוי הפרשני מבטל אוטומטית את כל ההרשעות הקודמות', 'אין לכך השלכה על נאשמים אחרים בשום מקרה'], 'c': 0, 'e': 'נכון. בעקבות הפירוש המצמצם שהתקבל בדיון הנוסף בשנת 2000 הוגשו בקשות של נאשמים שהורשעו לפי הפרשנות הקודמת.'}, {'q': 'לפי ס׳ 1 לחוק יסודות המשפט, באיזה מצב פונה בית המשפט לעקרונות החירות, הצדק, היושר והשלום של המשפט העברי ומורשת ישראל?', 'o': ['בכל פעם שלשון החוק אינה חד־משמעית', 'כשלא מצא תשובה לשאלה משפטית בחקיקה, בהלכה פסוקה או בדרך של היקש', 'כשהתכלית הסובייקטיבית מתנגשת עם האובייקטיבית', 'רק בעניינים של דיני משפחה'], 'c': 1, 'e': 'נכון. זה לשון הסעיף: המקור המשלים מופעל רק כשאין תשובה בחקיקה, בהלכה פסוקה או בהיקש — כלומר בלקונה.'}, {'q': 'בפרשת הנדלס נחלקו השופטים ברק ואלון בפירוש המונח "רשות" בחוק השבת אבדה. מה הייתה מהות המחלוקת?', 'o': ['האם לבית המשפט סמכות לדון בתביעת מוצא אבדה', 'האם יש לפנות למשפט העברי בפירוש המונח, משום שממנו נלקחו המונחים, או לפרשו לפי תכלית החוק הישראלי', 'האם החוק חל על בנקים', 'האם אבדה בחדר כספות היא "מציאה" לפי פקודת הראיות'], 'c': 1, 'e': 'נכון. אלון סבר שיש לפרש לפי הלכות השבת אבדה במשפט העברי; ברק סבר שהמונח מתפרש לפי תכלית החוק הישראלי.'}, {'q': 'מה מלמדת עמדת השופט שטיין בעע״מ 2484/23 קלמנט על המגמות העכשוויות בפרשנות?', 'o': ['שיש בעליון זרם המבקש לצמצם את השימוש בתכלית האובייקטיבית ולתת משקל רב יותר למשמעות הברורה של הלשון', 'שהעליון אימץ חובת פרשנות לטובת הרשות המינהלית', 'שהעליון נטש לחלוטין את הפרשנות התכליתית', 'שחוק הפרשנות בוטל'], 'c': 0, 'e': 'נכון. שטיין מבקר את "התכלית האובייקטיבית" ומדגיש שאין לתקן שגגה של המחוקק בניגוד למשמעות הברורה של החוק.'}, {'q': 'רשות המסים פרסמה חוזר שבו היא מפרשת סעיף בפקודת מס הכנסה. נישום טוען בבית המשפט לפירוש אחר. מה מעמד החוזר?', 'o': ['הוא מחייב את בית המשפט כמו חקיקת משנה', 'הוא אינו מחייב את בית המשפט, אף שיש לו משקל מעשי', 'בית המשפט חייב לאמץ אותו אם הוא סביר', 'הוא מחייב רק אם פורסם ברשומות'], 'c': 1, 'e': 'נכון. פרשנות של רשות אינה מחייבת את בית המשפט; רק מנגנונים כמו החלטת מיסוי מקדמית מחייבים את הרשות כלפי מי שקיבל אותה.'}, {'q': 'בבג״ץ חוק הלאום (2021) — מה הייתה עמדת דעת המיעוט של השופט קרא לגבי פרשנות מקיימת?', 'o': ['שאין להשתמש בפרשנות מקיימת לגבי חוקי יסוד בשום מקרה', 'שיש להחזיר את החוק לכנסת', 'שפרשנות מקיימת עדיפה תמיד על ביטול', 'שאי אפשר לבסס פרשנות מקיימת על "נדבך על נדבך" של הנחות שאינן כתובות בחוק'], 'c': 3, 'e': 'נכון. לדעתו לא היה אפשר להסתפק בפרשנות מקיימת הנשענת על הנחות שאינן כתובות, ולכן אין מתווה פרשני שמרפא את הפגם.'}, {'q': 'מה משמעות המשפט מפרשת מזרחי שמילות החוק הן "עטיפה לרעיון חי"?', 'o': ['שאין משמעות ללשון החוק', 'שהחוק מתפרש לאור תכליתו, שיכולה להתפתח עם נסיבות הזמן והמקום — פרשנות דינמית', 'שהמחוקק רשאי לשנות את פירוש החוק בהחלטה', 'שיש לפרש חוק לפי ההגדרה המילונית שהייתה בעת חקיקתו'], 'c': 1, 'e': 'נכון. זו מהות הפרשנות הדינמית: תכלית החוק "חיה" ומשתנה עם נסיבות הזמן.'}, {'q': 'נאשם הואשם בעבירה. אחרי ניתוח תכליתי מלא נמצא שלמונח שבעבירה יש פירוש סביר אחד בלבד, המחמיר עם הנאשם. בא כוחו מבקש להחיל את ס׳ 34כא. מה הדין?', 'o': ['ס׳ 34כא חל תמיד בחוק פלילי', 'בית המשפט יבחר בפירוש לשוני מקל אף שאינו סביר לפי התכלית', 'יש לזכות את הנאשם מחמת עקרון החוקיות בכל מקרה של מחלוקת פרשנית', 'ס׳ 34כא אינו חל, כי לא נותרו כמה פירושים סבירים לפי התכלית'], 'c': 3, 'e': 'נכון. הסעיף מותנה בקיום "פירושים סבירים אחדים לפי תכליתו"; כשהתכלית מובילה לפירוש סביר אחד — הוא אינו חל.'}]
MAR=[]
